// Expanded ZCL frame differential against pinned zigbee-herdsman 11.2.0.
// Fixtures are generated by tools/oracle/generate-zcl-pinned.mjs.

use serde::Deserialize;
use serde_json::Value;
use zigbee_apiarist::zspec::zcl::utils::{ClusterKey, CustomClusters, Utils};
use zigbee_apiarist::zspec::zcl::zcl_frame::{try_from_buffer, Frame, FrameParseError};
use zigbee_apiarist::zspec::zcl::zcl_header::Header;

#[derive(Debug, Deserialize)]
struct Fixture {
    revision: String,
    cases: Vec<Case>,
}

#[derive(Debug, Deserialize)]
struct Case {
    id: String,
    op: String,
    cluster: String,
    command: String,
    #[serde(rename = "frameType")]
    frame_type: Option<u8>,
    direction: Option<u8>,
    #[serde(rename = "disableDefaultResponse")]
    disable_default_response: Option<bool>,
    #[serde(rename = "manufacturerCode")]
    manufacturer_code: Option<u16>,
    #[serde(rename = "transactionSequenceNumber")]
    transaction_sequence_number: Option<u8>,
    payload: Option<Value>,
    #[serde(rename = "reservedBits")]
    reserved_bits: Option<u8>,
    buffer: Option<String>,
    #[serde(default)]
    expected: String,
    #[serde(rename = "expectedError", default)]
    expected_error: bool,
    /// Pinned upstream itself cannot re-decode this buffer (duplicate command
    /// ID resolved differently on create/decode). Both implementations must
    /// reject it.
    #[serde(rename = "upstreamDecodeError", default)]
    upstream_decode_error: bool,
}

fn bytes(hex: &str) -> Vec<u8> {
    (0..hex.len())
        .step_by(2)
        .map(|index| u8::from_str_radix(&hex[index..index + 2], 16).expect("hex"))
        .collect()
}
fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|byte| format!("{byte:02x}")).collect()
}

#[test]
fn zcl_frames_match_pinned_upstream() {
    let fixture: Fixture =
        serde_json::from_str(include_str!("fixtures/zcl-pinned.json")).expect("fixture");
    assert_eq!(fixture.revision, "zigbee-herdsman 11.2.0");
    let custom = CustomClusters::empty();
    let mut checked = 0;
    let mut failures = Vec::new();
    let mut upstream_decode_errors = 0;
    for case in fixture.cases {
        match case.op.as_str() {
            "frame_to_buffer" => {
                let command: &'static str = Box::leak(case.command.clone().into_boxed_str());
                let cluster: &'static str = Box::leak(case.cluster.clone().into_boxed_str());
                let frame = Frame::create(
                    case.frame_type.expect("frameType"),
                    case.direction.expect("direction"),
                    case.disable_default_response
                        .expect("disableDefaultResponse"),
                    case.manufacturer_code,
                    case.transaction_sequence_number.expect("tsn"),
                    command,
                    cluster,
                    case.payload.unwrap_or(Value::Null),
                    Value::Object(Default::default()),
                    case.reserved_bits.unwrap_or(0),
                );
                assert_eq!(hex(&frame.to_buffer()), case.expected, "{}", case.id);
                checked += 1;
            }
            "frame_from_buffer" => {
                let data = bytes(case.buffer.as_deref().expect("buffer"));
                if case.expected_error {
                    if case.upstream_decode_error {
                        upstream_decode_errors += 1;
                    }
                    assert!(
                        try_from_buffer(0x0006, None, &data, &custom).is_err(),
                        "{}",
                        case.id
                    );
                    checked += 1;
                    continue;
                }
                let cluster_id = if let Some(value) = case.cluster.strip_prefix("0x") {
                    u16::from_str_radix(value, 16).expect("cluster id")
                } else {
                    Utils::get_cluster(ClusterKey::Name(case.cluster.clone()), None, &custom).ID
                        as u16
                };
                let header = Header::from_buffer(&data).expect("header");
                match try_from_buffer(cluster_id, Some(header), &data, &custom) {
                    Ok(frame) => assert_eq!(hex(&frame.to_buffer()), case.expected, "{}", case.id),
                    Err(FrameParseError::Other(error)) => failures.push((
                        case.id.clone(),
                        case.cluster.clone(),
                        case.command.clone(),
                        format!("other:{error}"),
                    )),
                    Err(FrameParseError::Status(status)) => failures.push((
                        case.id.clone(),
                        case.cluster.clone(),
                        case.command.clone(),
                        format!("status:{status}"),
                    )),
                }
                checked += 1;
            }
            other => panic!("{}: unknown op {other}", case.id),
        }
    }
    if !failures.is_empty() {
        panic!(
            "{} frame failures (checked {}): {:?}",
            failures.len(),
            checked,
            failures
        );
    }
    assert!(checked > 400, "expected expanded corpus, got {checked}");
    assert_eq!(
        upstream_decode_errors, 2,
        "the duplicate-command-ID buffers must be asserted as errors on both sides"
    );
}

#[test]
fn zdo_constants_match_pinned_upstream() {
    use zigbee_apiarist::zspec::zdo::definition::clusters::ClusterId;
    #[derive(Deserialize)]
    struct ZdoFixture {
        constants: std::collections::BTreeMap<String, u16>,
    }
    let fixture: ZdoFixture =
        serde_json::from_str(include_str!("fixtures/zdo-pinned.json")).expect("zdo fixture");
    assert_eq!(fixture.constants.len(), 60);
    for (name, expected) in &fixture.constants {
        let actual = match name.as_str() {
            "ACTIVE_ENDPOINTS_REQUEST" => ClusterId::ACTIVE_ENDPOINTS_REQUEST,
            "ACTIVE_ENDPOINTS_RESPONSE" => ClusterId::ACTIVE_ENDPOINTS_RESPONSE,
            "BINDING_TABLE_REQUEST" => ClusterId::BINDING_TABLE_REQUEST,
            "BINDING_TABLE_RESPONSE" => ClusterId::BINDING_TABLE_RESPONSE,
            "BIND_REQUEST" => ClusterId::BIND_REQUEST,
            "BIND_RESPONSE" => ClusterId::BIND_RESPONSE,
            "CHALLENGE_REQUEST" => ClusterId::CHALLENGE_REQUEST,
            "CHALLENGE_RESPONSE" => ClusterId::CHALLENGE_RESPONSE,
            "CLEAR_ALL_BINDINGS_REQUEST" => ClusterId::CLEAR_ALL_BINDINGS_REQUEST,
            "CLEAR_ALL_BINDINGS_RESPONSE" => ClusterId::CLEAR_ALL_BINDINGS_RESPONSE,
            "DECOMMISSION_REQUEST" => ClusterId::DECOMMISSION_REQUEST,
            "DECOMMISSION_RESPONSE" => ClusterId::DECOMMISSION_RESPONSE,
            "END_DEVICE_ANNOUNCE" => ClusterId::END_DEVICE_ANNOUNCE,
            "GET_AUTHENTICATION_LEVEL_REQUEST" => ClusterId::GET_AUTHENTICATION_LEVEL_REQUEST,
            "GET_AUTHENTICATION_LEVEL_RESPONSE" => ClusterId::GET_AUTHENTICATION_LEVEL_RESPONSE,
            "GET_CONFIGURATION_REQUEST" => ClusterId::GET_CONFIGURATION_REQUEST,
            "GET_CONFIGURATION_RESPONSE" => ClusterId::GET_CONFIGURATION_RESPONSE,
            "IEEE_ADDRESS_REQUEST" => ClusterId::IEEE_ADDRESS_REQUEST,
            "IEEE_ADDRESS_RESPONSE" => ClusterId::IEEE_ADDRESS_RESPONSE,
            "LEAVE_REQUEST" => ClusterId::LEAVE_REQUEST,
            "LEAVE_RESPONSE" => ClusterId::LEAVE_RESPONSE,
            "LQI_TABLE_REQUEST" => ClusterId::LQI_TABLE_REQUEST,
            "LQI_TABLE_RESPONSE" => ClusterId::LQI_TABLE_RESPONSE,
            "MATCH_DESCRIPTORS_REQUEST" => ClusterId::MATCH_DESCRIPTORS_REQUEST,
            "MATCH_DESCRIPTORS_RESPONSE" => ClusterId::MATCH_DESCRIPTORS_RESPONSE,
            "NETWORK_ADDRESS_REQUEST" => ClusterId::NETWORK_ADDRESS_REQUEST,
            "NETWORK_ADDRESS_RESPONSE" => ClusterId::NETWORK_ADDRESS_RESPONSE,
            "NODE_DESCRIPTOR_REQUEST" => ClusterId::NODE_DESCRIPTOR_REQUEST,
            "NODE_DESCRIPTOR_RESPONSE" => ClusterId::NODE_DESCRIPTOR_RESPONSE,
            "NWK_BEACON_SURVEY_REQUEST" => ClusterId::NWK_BEACON_SURVEY_REQUEST,
            "NWK_BEACON_SURVEY_RESPONSE" => ClusterId::NWK_BEACON_SURVEY_RESPONSE,
            "NWK_ENHANCED_UPDATE_REQUEST" => ClusterId::NWK_ENHANCED_UPDATE_REQUEST,
            "NWK_ENHANCED_UPDATE_RESPONSE" => ClusterId::NWK_ENHANCED_UPDATE_RESPONSE,
            "NWK_IEEE_JOINING_LIST_REQUEST" => ClusterId::NWK_IEEE_JOINING_LIST_REQUEST,
            "NWK_IEEE_JOINING_LIST_RESPONSE" => ClusterId::NWK_IEEE_JOINING_LIST_RESPONSE,
            "NWK_UNSOLICITED_ENHANCED_UPDATE_RESPONSE" => {
                ClusterId::NWK_UNSOLICITED_ENHANCED_UPDATE_RESPONSE
            }
            "NWK_UPDATE_REQUEST" => ClusterId::NWK_UPDATE_REQUEST,
            "NWK_UPDATE_RESPONSE" => ClusterId::NWK_UPDATE_RESPONSE,
            "PARENT_ANNOUNCE" => ClusterId::PARENT_ANNOUNCE,
            "PARENT_ANNOUNCE_RESPONSE" => ClusterId::PARENT_ANNOUNCE_RESPONSE,
            "PERMIT_JOINING_REQUEST" => ClusterId::PERMIT_JOINING_REQUEST,
            "PERMIT_JOINING_RESPONSE" => ClusterId::PERMIT_JOINING_RESPONSE,
            "POWER_DESCRIPTOR_REQUEST" => ClusterId::POWER_DESCRIPTOR_REQUEST,
            "POWER_DESCRIPTOR_RESPONSE" => ClusterId::POWER_DESCRIPTOR_RESPONSE,
            "RETRIEVE_AUTHENTICATION_TOKEN_REQUEST" => {
                ClusterId::RETRIEVE_AUTHENTICATION_TOKEN_REQUEST
            }
            "RETRIEVE_AUTHENTICATION_TOKEN_RESPONSE" => {
                ClusterId::RETRIEVE_AUTHENTICATION_TOKEN_RESPONSE
            }
            "ROUTING_TABLE_REQUEST" => ClusterId::ROUTING_TABLE_REQUEST,
            "ROUTING_TABLE_RESPONSE" => ClusterId::ROUTING_TABLE_RESPONSE,
            "SET_CONFIGURATION_REQUEST" => ClusterId::SET_CONFIGURATION_REQUEST,
            "SET_CONFIGURATION_RESPONSE" => ClusterId::SET_CONFIGURATION_RESPONSE,
            "SIMPLE_DESCRIPTOR_REQUEST" => ClusterId::SIMPLE_DESCRIPTOR_REQUEST,
            "SIMPLE_DESCRIPTOR_RESPONSE" => ClusterId::SIMPLE_DESCRIPTOR_RESPONSE,
            "START_KEY_NEGOTIATION_REQUEST" => ClusterId::START_KEY_NEGOTIATION_REQUEST,
            "START_KEY_NEGOTIATION_RESPONSE" => ClusterId::START_KEY_NEGOTIATION_RESPONSE,
            "START_KEY_UPDATE_REQUEST" => ClusterId::START_KEY_UPDATE_REQUEST,
            "START_KEY_UPDATE_RESPONSE" => ClusterId::START_KEY_UPDATE_RESPONSE,
            "SYSTEM_SERVER_DISCOVERY_REQUEST" => ClusterId::SYSTEM_SERVER_DISCOVERY_REQUEST,
            "SYSTEM_SERVER_DISCOVERY_RESPONSE" => ClusterId::SYSTEM_SERVER_DISCOVERY_RESPONSE,
            "UNBIND_REQUEST" => ClusterId::UNBIND_REQUEST,
            "UNBIND_RESPONSE" => ClusterId::UNBIND_RESPONSE,
            other => panic!("missing Rust ZDO constant {other}"),
        };
        assert_eq!(actual, *expected, "{name}");
    }
}
